import { Course, ClassOffering, CuratedClass, CatalogEntry } from "./types";
import { courses, classes } from "./data";

function findCourse(courseId: string): Course {
  const course = courses.find((c) => c.courseId === courseId);
  if (!course) throw new Error(`Unknown courseId: ${courseId}`);
  return course;
}

