/** Simulates saving a curated class from a picker selection. */
export function curateClass(entry: CatalogEntry, text: string): CuratedClass {
  return {
    _id: `cur-${entry.classId}`,
    classId: entry.classId,
    subject: entry.subject,
    courseNumber: entry.courseNumber,
    sectionNumber: entry.sectionNumber,
    sessionId: entry.sessionId,
    text,
    createdAt: String(Date.now()),
  };
}

function searchableName(subject: string, number: string): string {
  return `${subject} ${number}`.toLowerCase();
}

/** Every whitespace-separated query token must appear somewhere in the haystack. */
function matches(query: string, haystack: string): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return q.split(/\s+/).every((token) => haystack.includes(token));
}

export function searchCatalog(
  query: string,
  entries: CatalogEntry[]
): CatalogEntry[] {
  return entries.filter((e) =>
    matches(query, `${searchableName(e.subject, e.courseNumber)} ${e.title.toLowerCase()}`)
  );
}

